package com.sami.app.uom.web;
import com.sami.app.common.api.ApiResponse; import com.sami.app.uom.dto.UomDtos.*; import com.sami.app.uom.service.UomService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.math.BigDecimal; import java.util.*;
@RestController @RequestMapping("/api/v1/uoms") @RequiredArgsConstructor public class UomController {private final UomService service; @GetMapping @PreAuthorize("@authz.has('products:view')") public ApiResponse<List<UomResponse>> list(){return ApiResponse.ok(service.list());} @PostMapping @PreAuthorize("@authz.has('products:create')") public ApiResponse<UomResponse> create(@Valid @RequestBody UomRequest r){return ApiResponse.ok(service.create(r));} @PutMapping("/{id}") @PreAuthorize("@authz.has('products:edit')") public ApiResponse<UomResponse> update(@PathVariable Long id,@Valid @RequestBody UomRequest r){return ApiResponse.ok(service.update(id,r));} @GetMapping("/conversions") @PreAuthorize("@authz.has('products:view')") public ApiResponse<List<ConversionResponse>> conversions(){return ApiResponse.ok(service.conversions());} @PostMapping("/conversions") @PreAuthorize("@authz.has('products:create')") public ApiResponse<ConversionResponse> conversion(@Valid @RequestBody ConversionRequest r){return ApiResponse.ok(service.createConversion(r));} @PutMapping("/conversions/{id}") @PreAuthorize("@authz.has('products:edit')") public ApiResponse<ConversionResponse> updateConversion(@PathVariable Long id,@Valid @RequestBody ConversionRequest r){return ApiResponse.ok(service.updateConversion(id,r));} @GetMapping("/convert") @PreAuthorize("@authz.has('products:view')") public ApiResponse<QuantityConversion> convert(@RequestParam BigDecimal quantity,@RequestParam Long fromUomId,@RequestParam Long toUomId){return ApiResponse.ok(service.convert(quantity,fromUomId,toUomId));}}
